/* @autogenerated */
import { ComponentFixture, TestBed } from '@angular/core/testing';
import { BehaviorSubject, of, Subject } from 'rxjs';
import { Router } from '@angular/router';
import { MenuComponent } from './menu.component';
import { AppStateService } from '@shared/context/state/app-state.service';
import { IdentityService } from '@shared/context/identity/identity.service';
import { AppConfigService } from '@shared/context/config/app-config.service';
import { RouteAccessService } from './route-accessible.service';
import { MenuItem } from '../menu-item.model';

describe('MenuComponent', () => {
  let fixture: ComponentFixture<MenuComponent>;
  let component: MenuComponent;
  let routerEvents$: Subject<any>;
  let routerMock: any;
  let checkerMock: any;
  let identityMock: any;
  let appStateMock: any;

  beforeEach(async () => {
    routerEvents$ = new Subject();
    routerMock = {
      events: routerEvents$.asObservable(),
      navigate: jasmine.createSpy('navigate'),
    };

    checkerMock = {
      isUrlActive: jasmine.createSpy('isUrlActive').and.returnValue(false),
      checkRouteGuards: jasmine.createSpy('checkRouteGuards').and.returnValue(of(true)),
    };

    identityMock = {
      login: jasmine.createSpy('login'),
      logout: jasmine.createSpy('logout'),
    };

    const lang$ = new BehaviorSubject<string>('es');
    (lang$ as any).set = (value: string) => lang$.next(value);
    const tenant$ = new BehaviorSubject<string>('main');
    (tenant$ as any).set = (value: string) => tenant$.next(value);

    appStateMock = {
      language: lang$,
      tenant: tenant$,
    };

    await TestBed.configureTestingModule({
      imports: [MenuComponent],
      providers: [
        { provide: Router, useValue: routerMock },
        { provide: RouteAccessService, useValue: checkerMock },
        { provide: IdentityService, useValue: identityMock },
        { provide: AppStateService, useValue: appStateMock },
        { provide: AppConfigService, useValue: { 'meta.title': of('LughAuth') } },
      ],
    }).compileComponents();

    fixture = TestBed.createComponent(MenuComponent);
    component = fixture.componentInstance;
    fixture.detectChanges();
  });

  it('builds computed menu from input items', () => {
    const items: MenuItem[] = [{ label: 'Users', route: 'users' }];
    fixture.componentRef.setInput('items', items);
    fixture.detectChanges();

    expect(component.menu().length).toBe(1);
    expect(component.menu()[0].label).toBe('Users');
  });

  it('run emits select and navigates when route exists', () => {
    const item: MenuItem = { label: 'Users', route: 'users' };
    let emitted: MenuItem | undefined;
    component.select.subscribe((value) => (emitted = value));

    component.run(item, null);

    expect(emitted).toEqual(item);
    expect(routerMock.navigate).toHaveBeenCalledWith(['es', 'main', 'users']);
  });

  it('run shows alert when route is missing', () => {
    spyOn(window, 'alert');
    component.run({ label: 'Group only' }, null);
    expect(window.alert).toHaveBeenCalledWith('No route');
  });

  it('updates language and tenant state through helper methods', () => {
    component.idioma('en');
    component.tenant('acme');

    expect(appStateMock.language.value).toBe('en');
    expect(appStateMock.tenant.value).toBe('acme');
  });

  it('delegates login and logout to IdentityService', () => {
    component.login();
    component.logout();

    expect(identityMock.login).toHaveBeenCalledWith('main');
    expect(identityMock.logout).toHaveBeenCalledWith('main');
  });

  it('sets parent group visibility based on children route guards', () => {
    checkerMock.checkRouteGuards.and.returnValue(of(false));
    checkerMock.isUrlActive.and.returnValue(false);

    fixture.componentRef.setInput('items', [
      {
        label: 'Access',
        subItems: [{ label: 'Users', route: 'users' }],
      },
    ]);
    fixture.detectChanges();

    const group = component.menu()[0];
    expect(group.hidden).toBeTrue();
    expect(group.active).toBeUndefined();
  });

  it('recomputes active state on router events', () => {
    checkerMock.isUrlActive.and.returnValues(false, true);
    fixture.componentRef.setInput('items', [{ label: 'Users', route: 'users' }]);
    fixture.detectChanges();

    expect(component.menu()[0].active).toBeFalse();
    routerEvents$.next({ type: 'NavigationEnd' });
    expect(component.menu()[0].active).toBeTrue();
  });

  it('recomputes parent visibility when child route changes on router events', () => {
    checkerMock.checkRouteGuards.and.returnValue(of(true));
    checkerMock.isUrlActive.and.returnValues(false, true);

    fixture.componentRef.setInput('items', [
      {
        label: 'Access',
        subItems: [{ label: 'Users', route: 'users' }],
      },
    ]);
    fixture.detectChanges();

    const parent = component.menu()[0];
    expect(parent.active).toBeUndefined();

    routerEvents$.next({ type: 'NavigationEnd' });

    expect(parent.active).toBeTruthy();
    expect(parent.childs[0].active).toBeTrue();
  });
});
